alter table public.notas_fiscais add column if not exists status_fiscal text; alter table public.notas_fiscais add column if not exists nfse_dps_id text; alter table public.notas_fiscais add column if not exists nfse_ambiente text; alter table public.notas_fiscais add column if not exists nfse_codigo_verificacao text; alter table public.notas_fiscais add column if not exists nfse_dados jsonb; create unique index if not exists notas_nfse_empresa_numero_uq on public.notas_fiscais(empresa_id,numero_nf) where numero_nf is not null and origem='NFSE_NACIONAL' and apagado=false;